 void Update(){while(nativeMessages.TryDequeue(out var message)){if(message=="HIDDEN|"+closeToken&&!opened)nativeHidden=true;}if(restoringInput&&(nativeHidden||Time.realtimeSinceStartup>=restoreDeadline||child==null||child.HasExited)&&(!RelicCore.Instance||!RelicCore.Instance.Retracting))FinishClose(true);while(nativeErrors.TryDequeue(out var nativeError)){error="Scratch 编辑器错误："+nativeError;Toggle(false);Send("QUIT");}if(opened&&!BackgroundReview&&!nativeReady&&Time.realtimeSinceStartup>readyDeadline){error="Scratch 编辑器启动超时，请检查 WebView2 Runtime 是否可用";Toggle(false);Send("QUIT");}if(Input.GetKeyDown(KeyCode.Tab))HandleShortcut(KeyCode.Tab);if(opened&&Input.GetKeyDown(KeyCode.Escape))HandleShortcut(KeyCode.Escape);UpdatePlayerWindow();while(requests.TryDequeue(out var req)){var chapter=FindAnyObjectByType<BeachChapter>();var result=new Response{lesson=chapter&&chapter.Teaching};try{if(req.body==null){result.name=data.name;result.workspace=data.workspace;result.graph=data.graph;result.message=error.Length>0?error:!string.IsNullOrEmpty(data.workspace)?"草稿已恢复":"新程序 · 编辑后自动保存";if(error.Length>0)result.ok=false;}else{var m=JsonUtility.FromJson<Message>(req.body);if(m.type=="save"){ProgramCodec.Read(m.graph);var next=new SaveData{name=m.name,workspace=m.workspace,graph=m.graph};File.WriteAllText(path+".tmp",JsonUtility.ToJson(next,true));if(File.Exists(path))File.Replace(path+".tmp",path,path+".bak");else File.Move(path+".tmp",path);data=next;result.message="已自动保存";error="";}if(m.type=="close")Toggle(false);if(m.type=="check"||m.type=="preview"){var d=ProgramCodec.Read(m.graph);foreach(var i in ProgramValidator.Validate(d))result.issues.Add(new Issue{blockId=i.blockId,message=i.message});if(m.adapterErrors!=null)result.issues.AddRange(m.adapterErrors);result.report=result.issues.Count>0?"程序存在错误":m.type=="preview"?ProgramPreview.Trace(d):"✓ 检查通过 · 可预览；运行时还会检查动作可用性";}if(m.type=="run"){var d=ProgramCodec.Read(m.graph);var issue=result.lesson?chapter.LessonIssue(d):null;if(issue