public static class ProgramPreview {
 public static string Trace(Draft d){int budget=400;var text=new StringBuilder("编辑器执行预览（模拟条件，不操作世界）\n");Action<List<Block>,int> visit=null;visit=(list,depth)=>{foreach(var b in list){if(--budget<0)return;text.Append(' ',depth*2).Append(BlockCatalog.All[b.kind].name);if(b.kind==2||b.kind==3||b.kind==10||b.kind==11)text.Append(" ").Append(b.value);text.AppendLine();if(b.kind==2){float n;ProgramValidator.Number(b.value,out n);for(int i=0;i<(int)n&&budget>0;i++)visit(b.children,depth+1);}if(b.kind==4){float l,r;bool pass=b.condition.kind==5?b.condition.value=="true":ProgramValidator.Number(b.condition.value,out l)&&ProgramValidator.Number(b.condition.right,out r)&&l>r;if(pass)visit(b.children,depth+1);}}};visit(d.blocks,0);if(budget<=0)text.AppendLine("预览达到400条安全上限");return text.ToString();}
}
